126	告警规则(rule / evaluate / alerts / ack):
127	  规则标识非空且在设备与分组两类规则间唯一(去首尾空白、区分大小写);用
128	  --device 绑定一个已有存储读数的设备,或用 --group 绑定一个已有分组(二者
129	  恰好其一);设备与分组即使同名也是不同目标,列表与历史均显示目标类型。
130	  阈值非负、最多三位小数 kWh;目标与阈值创建后固定,分组规则绑定分组标识、
131	  不冻结创建时成员。相同标识、同目标类型、同目标标识及等价阈值重试成功且
132	  不重复创建,任一不同即报冲突。
133	  evaluate 的 --from/--to 为 YYYY-MM-DD 的 UTC 日期,起日含、止日不含,
134	  起日必须更早。设备规则评估口径与 daily 相同;分组规则与 group daily 的
135	  联合覆盖口径相同:每天按当时生效的成员版本计算,允许日内切换,首个版本
136	  生效前为未知,任一成员下降为异常,否则任一成员未知为未知;成员切换不
137	  重置各设备原读数区间的分摊起点。仅全天有效覆盖的日期可判定,消耗严格
138	  大于阈值才超限(等于为正常),零增长有效;有未知或下降覆盖的日期不可
139	  判定,不触发也不恢复。每个规则每个日期独立跟踪:首次超限创建带全局
140	  唯一标识的未确认告警,重复超限保留原标识;完整评估正常才记录恢复;恢复
141	  后再超限创建新的未确认告警,旧记录保留,原确认不转移。批量日期评估要么
142	  全部提交要么不提交。
143	  ack 按告警标识确认,已恢复告警也可确认;重复确认成功且不重复记事,确认
144	  不改变超限或恢复状态。alerts 按规则和日期展示当前计算的消耗或不可判定
145	  原因、各次告警的标识、检测状态、确认状态及按发生顺序排列的触发/恢复/
146	  确认事件(触发、恢复时的消耗为当时记录,不随后续数据改写);省略日期
147	  范围时展示有告警记录的全部日期;查询只读,不会隐式恢复。导入读数或补录
148	  成员版本都不自动评估,需显式重评才更新检测状态。
149	
150	CSV 格式:
151	  表头: ${CSV_HEADER}
152	  device   设备标识(区分大小写,首尾空白忽略,去空白后不能为空)
153	  time     秒精度 ISO8601,带 Z 或数字时区偏移;必须是真实日期
154	  reading  累计电表读数(kWh,非负,最多三位小数;可超出 Number 安全整数
155	           范围,任意大的十进制值都精确保存,如 9007199254740.991)
156	  支持标准双引号字段与 "" 转义;同一设备同一时刻(按实际时刻判定)
157	  重复且数值相同记为重复跳过,数值不同视为冲突并拒绝整批。
158	
159	数值精度:
160	  读数与阈值以毫千瓦时 BigInt 运算,解析、求差、分摊、汇总、比较、保存
161	  和显示全程精确,输出固定三位小数,不使用科学计数法。
162	  兼容旧版 readings.json / alerts.json 中以 JSON 数值保存的安全整数
163	  读数与阈值,无需手工转换;新版以十进制字符串保存。数值型毫千瓦时若
164	  已超出安全整数范围(精度已丢失)按损坏数据拒绝,不猜测原值。
165	
166	数据位置:
167	  $METERWATCH_DATA_DIR/readings.json(默认 ~/.meterwatch/readings.json;
168	           读数与修正、撤销历史同文件保存,旧版无修正与撤销历史的文件可直接使用)
169	  $METERWATCH_DATA_DIR/alerts.json(告警规则与历史,与读数文件相互独立)
170	  $METERWATCH_DATA_DIR/groups.json(分组配置,与读数、告警文件相互独立)
171	
172	退出码: 0 成功;1 数据或读写错误;2 参数错误`;
173	
174	function usageError(message: string): number {
175	  console.error(`${name}: ${message}`);
176	  console.error(`用法见 'node app.ts --help'`);
177	  return 2;
178	}
179	
180	interface ParsedOptions {
181	  devices: string[];
182	  from?: number;
183	  to?: number;
184	  tz?: string;
185	}
186	
187	/** 解析 --device/--from/--to(及允许时的 --tz)选项;出错返回错误消息字符串。 */
188	function parseOptions(rest: string[], allowTz = false): ParsedOptions | string {
189	  const devices: string[] = [];
190	  let from: number | undefined;
191	  let to: number | undefined;
192	  let tz: string | undefined;
193	  for (let i = 0; i < rest.length; i++) {
194	    let opt = rest[i];
195	    let value: string | undefined;
196	    const eq = opt.indexOf('=');
197	    if (opt.startsWith('--') && eq !== -1) {
198	      value = opt.slice(eq + 1);
199	      opt = opt.slice(0, eq);
200	    } else if (opt.startsWith('--')) {
201	      value = rest[i + 1];
202	      if (value === undefined) return `选项 '${opt}' 缺少值`;
203	      i++;
204	    } else {
205	      return `无法识别的参数 '${opt}'`;
206	    }
207	    if (opt === '--device') {
208	      if (value.trim() === '') return "'--device' 的值不能为空";
209	      devices.push(value);
210	    } else if (opt === '--from' || opt === '--to') {
211	      const ts = parseIso8601(value.trim());
212	      if (ts === null) {
213	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
214	      }
215	      if (opt === '--from') from = ts;
216	      else to = ts;
217	    } else if (opt === '--tz' && allowTz) {
218	      tz = value.trim();
219	      if (tz === '') return "'--tz' 的值不能为空";
220	    } else {
221	      return `无法识别的选项 '${opt}'`;
222	    }
223	  }
224	  return { devices, from, to, tz };
225	}
226	
227	/** 校验 IANA 分日时区名;无效时返回错误消息字符串。 */
228	function checkTz(tz: string): string | null {
229	  if (loadTimezone(tz) === null) {
230	    return `未知时区 '${tz}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`;
231	  }
232	  return null;
233	}
234	
235	/** 解析 --opt value / --opt=value 形式的选项;出错返回错误消息字符串。 */
236	function parseFlags(rest: string[], allowed: string[]): Map<string, string[]> | string {
237	  const out = new Map<string, string[]>();
238	  for (let i = 0; i < rest.length; i++) {
239	    let opt = rest[i];
240	    let value: string | undefined;
241	    const eq = opt.indexOf('=');
242	    if (opt.startsWith('--') && eq !== -1) {
243	      value = opt.slice(eq + 1);
244	      opt = opt.slice(0, eq);
245	    } else if (opt.startsWith('--')) {
246	      value = rest[i + 1];
247	      if (value === undefined) return `选项 '${opt}' 缺少值`;
248	      i++;
249	    } else {
250	      return `无法识别的参数 '${opt}'`;
251	    }
252	    if (!allowed.includes(opt)) return `无法识别的选项 '${opt}'`;
253	    const list = out.get(opt);
254	    if (list) list.push(value);
255	    else out.set(opt, [value]);
256	  }
257	  return out;
258	}
259	
260	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
261	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
262	  const list = flags.get(name);
263	  if (!list || list.length !== 1) return null;
264	  return list[0];
265	}
266	
267	/** 解析 YYYY-MM-DD 日期选项;无效时返回错误消息字符串。 */
268	function dateFlag(value: string, label: string): number | string {
269	  const ts = parseUtcDate(value.trim());
270	  if (ts === null) return `${label}无效: '${value.trim()}'(需 YYYY-MM-DD 的真实 UTC 日期)`;
271	  return ts;
272	}
273	
274	function cmdRule(rest: string[]): number {
275	  const [sub, ...subrest] = rest;
276	  if (sub === 'list') {
277	    if (subrest.length !== 0) return usageError("'rule list' 不接受参数");
278	    return cmdRuleList();
279	  }
280	  if (sub === 'create') {
281	    const flags = parseFlags(subrest, ['--id', '--device', '--group', '--threshold']);
282	    if (typeof flags === 'string') return usageError(flags);
283	    const idRaw = oneFlag(flags, '--id');
284	    const deviceList = flags.get('--device');
285	    const groupList = flags.get('--group');
286	    const thresholdRaw = oneFlag(flags, '--threshold');
287	    if (idRaw === null || thresholdRaw === null) {
288	      return usageError("'rule create' 需要 --id 与 --threshold 各恰好一个");
289	    }
290	    const hasDevice = deviceList !== undefined;
291	    const hasGroup = groupList !== undefined;
292	    if (hasDevice === hasGroup) {
293	      return usageError("'rule create' 需恰好提供 --device <设备> 或 --group <分组> 之一");
294	    }
295	    if ((deviceList !== undefined && deviceList.length !== 1) ||
296	      (groupList !== undefined && groupList.length !== 1)) {
297	      return usageError("'rule create' 的目标选项只能出现一次");
298	    }
299	    const id = idRaw.trim();
300	    if (id === '') return usageError('规则标识不能为空');
301	    const thresholdMilli = parseKwh(thresholdRaw.trim());
302	    if (thresholdMilli === null) {
303	      return usageError(`阈值无效: '${thresholdRaw.trim()}'(需非负、最多三位小数的 kWh)`);
304	    }
