444	/**
445	 * 解析 correct 的修正项:以裸 '--item' 分段,每段需 --device/--at/--expect/--set
446	 * 各恰好一个。出错返回错误消息字符串。
447	 */
448	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
449	  const segments: string[][] = [[]];
450	  for (const tok of rest) {
451	    if (tok === '--item') segments.push([]);
452	    else segments[segments.length - 1].push(tok);
453	  }
454	  const headFlags = parseFlags(segments[0], ['--request']);
455	  if (typeof headFlags === 'string') return headFlags;
456	  const requestRaw = oneFlag(headFlags, '--request');
457	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
458	  const requestId = requestRaw.trim();
459	  if (requestId === '') return '请求标识不能为空';
460	  const itemSegs = segments.slice(1);
461	  if (itemSegs.length === 0) {
462	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
463	  }
464	  const items: CorrectionItem[] = [];
465	  for (const seg of itemSegs) {
466	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
467	    if (typeof flags === 'string') return flags;
468	    const deviceRaw = oneFlag(flags, '--device');
469	    const atRaw = oneFlag(flags, '--at');
470	    const expectRaw = oneFlag(flags, '--expect');
471	    const setRaw = oneFlag(flags, '--set');
472	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
473	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
474	    }
475	    const device = deviceRaw.trim();
476	    if (device === '') return "'--device' 的值不能为空";
477	    const ts = parseIso8601(atRaw.trim());
478	    if (ts === null) {
479	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
480	    }
481	    const expectedMilli = parseKwh(expectRaw.trim());
482	    if (expectedMilli === null) {
483	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
484	    }
485	    const replacementMilli = parseKwh(setRaw.trim());
486	    if (replacementMilli === null) {
487	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
488	    }
489	    items.push({ device, ts, expectedMilli, replacementMilli });
490	  }
491	  return { requestId, items };
492	}
493	
494	function cmdCorrectEntry(rest: string[]): number {
495	  const parsed = parseCorrectItems(rest);
496	  if (typeof parsed === 'string') return usageError(parsed);
497	  return cmdCorrect(parsed.requestId, parsed.items);
498	}
499	
500	function cmdUndoEntry(rest: string[]): number {
501	  const flags = parseFlags(rest, ['--request', '--target']);
502	  if (typeof flags === 'string') return usageError(flags);
503	  const requestRaw = oneFlag(flags, '--request');
504	  const targetRaw = oneFlag(flags, '--target');
505	  if (requestRaw === null || targetRaw === null) {
506	    return usageError("'undo' 需要 --request 与 --target 各恰好一个");
507	  }
508	  const requestId = requestRaw.trim();
509	  if (requestId === '') return usageError('撤销请求标识不能为空');
510	  const targetId = targetRaw.trim();
511	  if (targetId === '') return usageError('目标修正请求标识不能为空');
512	  return cmdUndo(requestId, targetId);
513	}
