532	    const parsed = parseOptions(rest);
533	    if (typeof parsed === 'string') return usageError(parsed);
534	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
535	      return usageError('查询起点必须早于终点(--from < --to)');
536	    }
537	    return cmdReadings(parsed);
