1	// 每日能耗阈值告警:规则管理、评估、告警历史查询与确认。
2	//
3	// 规则分两类,由 targetType 区分:
4	// - device 规则绑定一个已有设备;
5	// - group 规则绑定一个已有分组标识(不冻结创建时成员,每天按当时生效的成员
6	//   版本计算,允许日内切换)。
7	// 设备与分组即使同名也是不同目标;规则标识在两类规则间统一唯一(去首尾空白、
8	// 区分大小写)。阈值为非负、最多三位小数的 kWh,绑定目标与阈值创建后固定。
9	// 相同标识、同目标类型、同目标标识及等价阈值重试成功且不重复创建,异参报冲突。
10	//
11	// - 评估针对连续完整 UTC 日期(起日含、止日不含)。设备规则复用 daily 的完整
12	//   时序、均匀分摊与累计比例向下取整口径;分组规则复用 group daily 的联合覆盖
13	//   口径:每天按当时生效的成员版本切分时段(允许日内切换),任一成员下降为异常,
14	//   否则任一成员未知为未知,首个版本生效前为未知;成员切换不重置各设备原读数
15	//   区间的分摊起点。仅全天有效覆盖的日期可判定,消耗严格大于阈值才超限,等于
16	//   阈值视为正常;有未知或下降覆盖时不可判定,不触发也不恢复;零增长是有效数据。
17	// - 每条规则的每个日期独立跟踪:首次判定超限创建全局唯一标识的未确认告警,
18	//   重复超限保留原标识且不新增事件;后续完整评估正常才记录恢复;恢复后再
19	//   超限创建新的未确认告警,旧记录保留,原确认不转移给新告警。
20	// - 确认按告警标识,已恢复告警也可确认;重复确认成功且不重复记事;确认不
21	//   改变超限或恢复状态。
22	// - 规则与历史存于数据目录的 alerts.json(与 readings.json、groups.json 相互
23	//   独立,导入与补录成员版本都不会自动评估)。创建、评估、确认都先在内存完成
24	//   全部计算再一次性原子写入,任何失败不留下部分状态;损坏或不可读存储明确
25	//   报错,绝不当作空库。旧版仅含 device 字段的规则无需手工转换即可继续使用。
26	
27	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
28	import { dirname } from 'node:path';
29	import {
30	  alertFilePath,
31	  dataFilePath,
32	  groupFilePath,
33	  loadStore,
34	  parseStoredMilli,
35	  StoreError,
36	  type Reading,
37	} from './store.ts';
38	import { computeDay, DAY_SECONDS, type DayStats } from './report.ts';
39	import { computeGroupSegment, loadCheckedSeriesByDevice, loadGroups, type Group } from './groups.ts';
40	import { formatIsoUtc, parseIso8601 } from './time.ts';
41	import { formatKwh } from './value.ts';
42	
43	export type RuleTargetType = 'device' | 'group';
44	
45	export interface AlertRule {
46	  /** 规则标识(非空、唯一,已去首尾空白,设备与分组规则间统一唯一)。 */
47	  id: string;
48	  /** 目标类型:设备或分组。 */
49	  targetType: RuleTargetType;
50	  /** 绑定的设备或分组标识(已去首尾空白,区分大小写),创建后固定。 */
51	  targetId: string;
52	  /** 阈值,毫千瓦时 BigInt,创建后固定。 */
53	  thresholdMilli: bigint;
54	}
55	
56	export type AlertEventType = 'triggered' | 'recovered' | 'acknowledged';
57	
58	export interface AlertEvent {
59	  /** 全局单调递增序号,决定触发/恢复/确认的处理顺序。 */
60	  seq: number;
61	  type: AlertEventType;
62	  /** 触发/恢复时该日的分摊消耗(毫千瓦时十进制字符串,可能超出 Number 安全范围)。 */
63	  consumptionMilli?: string;
64	}
65	
66	export interface AlertRecord {
67	  /** 告警标识,全局唯一(设备与分组规则共用编号空间)。 */
68	  id: string;
69	  ruleId: string;
70	  /** UTC 日期,YYYY-MM-DD。 */
71	  date: string;
72	  /** 检测状态:triggered 超限未恢复;recovered 已恢复。 */
73	  status: 'triggered' | 'recovered';
74	  acknowledged: boolean;
75	  events: AlertEvent[];
76	}
77	
78	interface AlertState {
79	  nextAlertNum: number;
80	  nextEventSeq: number;
81	  rules: AlertRule[];
82	  alerts: AlertRecord[];
83	}
84	
85	function err(message: string): void {
86	  console.error(`meterwatch: ${message}`);
87	}
88	
89	function emptyState(): AlertState {
90	  return { nextAlertNum: 1, nextEventSeq: 1, rules: [], alerts: [] };
91	}
