93	/** 目标在输出中的显示形式,如 device=meter-1 / group=floor-1。 */
94	function targetLabel(rule: Pick<AlertRule, 'targetType' | 'targetId'>): string {
95	  return `${rule.targetType}=${rule.targetId}`;
96	}
