98	/** 读取告警存储;文件不存在返回空状态,存在但无法读取或内容损坏抛出 StoreError。 */
99	function loadAlertState(path: string): AlertState {
100	  let text: string;
101	  try {
102	    text = readFileSync(path, 'utf8');
103	  } catch (e) {
104	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyState();
105	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
106	  }
107	  let data: unknown;
108	  try {
109	    data = JSON.parse(text);
110	  } catch {
111	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
112	  }
113	  const bad = (what: string): StoreError =>
114	    new StoreError(`storage file ${path} is corrupted (${what})`);
115	  const o = data as Record<string, unknown>;
116	  if (o === null || typeof o !== 'object') throw bad('not an object');
117	  if (!Number.isSafeInteger(o.nextAlertNum) || (o.nextAlertNum as number) < 1) {
118	    throw bad('invalid nextAlertNum');
119	  }
120	  if (!Number.isSafeInteger(o.nextEventSeq) || (o.nextEventSeq as number) < 1) {
121	    throw bad('invalid nextEventSeq');
122	  }
123	  if (!Array.isArray(o.rules)) throw bad('missing rules array');
124	  if (!Array.isArray(o.alerts)) throw bad('missing alerts array');
125	
126	  const ruleIds = new Set<string>();
127	  const rules: AlertRule[] = [];
128	  for (const r of o.rules as Array<Record<string, unknown>>) {
129	    // 阈值兼容旧格式的安全整数数值;超出安全整数范围的数值型阈值精度已丢失,
130	    // 按损坏数据拒绝,不猜测原值。
131	    const thresholdMilli = r !== null && typeof r === 'object' ? parseStoredMilli(r.thresholdMilli) : null;
132	    if (
133	      r === null ||
134	      typeof r !== 'object' ||
135	      typeof r.id !== 'string' ||
136	      r.id.length === 0 ||
137	      thresholdMilli === null
138	    ) {
139	      throw bad('invalid rule entry');
140	    }
141	    // 目标类型:新版字段 targetType/targetId;旧版只有 device 字段,按 device 规则
142	    // 读入,已有设备规则无需手工转换即可继续使用。
143	    let targetType: RuleTargetType;
144	    let targetId: string;
145	    if (r.targetType === undefined) {
146	      if (typeof r.device !== 'string' || r.device.length === 0) throw bad('invalid rule entry');
147	      targetType = 'device';
148	      targetId = r.device;
149	    } else {
150	      if (r.targetType !== 'device' && r.targetType !== 'group') {
151	        throw bad(`invalid targetType in rule '${r.id}'`);
152	      }
153	      if (typeof r.targetId !== 'string' || r.targetId.length === 0) {
154	        throw bad(`invalid targetId in rule '${r.id}'`);
155	      }
156	      targetType = r.targetType;
157	      targetId = r.targetId;
158	    }
159	    if (ruleIds.has(r.id)) throw bad(`duplicate rule id '${r.id}'`);
160	    ruleIds.add(r.id);
161	    rules.push({ id: r.id, targetType, targetId, thresholdMilli: thresholdMilli as bigint });
162	  }
163	
164	  const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
165	  const alertIds = new Set<string>();
166	  for (const a of o.alerts as Array<Record<string, unknown>>) {
167	    const ok =
168	      a !== null &&
169	      typeof a === 'object' &&
170	      typeof a.id === 'string' &&
171	      a.id.length > 0 &&
172	      typeof a.ruleId === 'string' &&
173	      ruleIds.has(a.ruleId) &&
174	      typeof a.date === 'string' &&
175	      DATE_RE.test(a.date) &&
176	      (a.status === 'triggered' || a.status === 'recovered') &&
177	      typeof a.acknowledged === 'boolean' &&
178	      Array.isArray(a.events) &&
179	      (a.events as unknown[]).length > 0;
180	    if (!ok) throw bad('invalid alert entry');
181	    if (alertIds.has(a.id)) throw bad(`duplicate alert id '${a.id}'`);
182	    alertIds.add(a.id);
183	    const seqs = new Set<number>();
184	    for (const e of a.events as Array<Record<string, unknown>>) {
185	      const eok =
186	        e !== null &&
187	        typeof e === 'object' &&
188	        Number.isSafeInteger(e.seq) &&
189	        (e.seq as number) >= 1 &&
190	        (e.type === 'triggered' || e.type === 'recovered' || e.type === 'acknowledged') &&
191	        (e.consumptionMilli === undefined ||
192	          (typeof e.consumptionMilli === 'string' && /^\d+$/.test(e.consumptionMilli)));
193	      if (!eok) throw bad('invalid alert event');
194	      if (seqs.has(e.seq as number)) throw bad(`duplicate event seq in alert '${a.id}'`);
195	      seqs.add(e.seq as number);
196	    }
197	  }
198	  return {
199	    nextAlertNum: o.nextAlertNum as number,
200	    nextEventSeq: o.nextEventSeq as number,
201	    rules,
202	    alerts: o.alerts as unknown as AlertRecord[],
203	  };
204	}
