206	/**
207	 * 原子写入告警存储;失败抛错,原有数据保持不变。
208	 * 告警写入不触碰读数与成员版本文件。
209	 */
210	function saveAlertState(path: string, state: AlertState): void {
211	  mkdirSync(dirname(path), { recursive: true });
212	  const tmp = `${path}.tmp-${process.pid}`;
213	  const body =
214	    JSON.stringify(
215	      {
216	        version: 2,
217	        ...state,
218	        rules: state.rules.map((r) => ({
219	          id: r.id,
220	          targetType: r.targetType,
221	          targetId: r.targetId,
222	          thresholdMilli: r.thresholdMilli.toString(),
223	        })),
224	      },
225	      null,
226	      2,
227	    ) + '\n';
228	  try {
229	    writeFileSync(tmp, body, 'utf8');
230	    renameSync(tmp, path);
231	  } catch (e) {
232	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
233	  }
234	}
