253	/**
254	 * 分组规则的评估环境:绑定分组与全库设备时序。
255	 * 读取读数时拒绝全库重复身份,包括不属于该分组的设备。
256	 */
257	interface GroupEnv {
258	  kind: 'group';
259	  group: Group;
260	  byDevice: Map<string, Reading[]>;
261	}
262	
263	interface DeviceEnv {
264	  kind: 'device';
265	  series: Reading[];
266	}
267	
268	type RuleEnv = DeviceEnv | GroupEnv;
269	
270	/** 为规则准备评估环境;未知分组或存储损坏抛 StoreError。 */
271	function prepareEnv(rule: AlertRule): RuleEnv {
272	  if (rule.targetType === 'device') {
273	    return { kind: 'device', series: deviceSeries(rule.targetId) };
274	  }
275	  const groups = loadGroups(groupFilePath());
276	  const group = groups.find((g) => g.id === rule.targetId);
277	  if (!group) {
278	    throw new StoreError(
279	      `unknown group '${rule.targetId}' bound by rule '${rule.id}' (groups storage has no such group)`,
280	    );
281	  }
282	  const byDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
283	  return { kind: 'group', group, byDevice };
284	}
