286	/** 不可判定原因(未知/异常覆盖秒数)。 */
287	function undecidableReason(stats: Pick<DayStats, 'unknown' | 'anomaly'>): string {
288	  return `undecidable (unknown=${stats.unknown}s anomaly=${stats.anomaly}s)`;
289	}
