291	/**
292	 * 计算规则在完整 UTC 日 [dayStart, dayStart+86400) 上的统计。
293	 * 设备规则用 daily 口径,分组规则用 group daily 的联合覆盖口径。
294	 */
295	function computeRuleDay(rule: AlertRule, env: RuleEnv, dayStart: number): DayStats {
296	  const dayEnd = dayStart + DAY_SECONDS;
297	  if (env.kind === 'device') {
298	    return computeDay(env.series, dayStart, dayEnd);
299	  }
300	  const stats = computeGroupSegment(env.group.versions, env.byDevice, dayStart, dayEnd);
301	  return {
302	    valid: stats.valid,
303	    anomaly: stats.anomaly,
304	    unknown: stats.unknown,
305	    consumption: stats.consumption,
306	  };
307	}
