526	/**
527	 * 查询规则的告警历史。只读,不修改数据,也不会隐式恢复。
528	 * 给定日期范围时逐日展示当前计算的消耗或不可判定原因及各次告警;省略范围时
529	 * 展示有告警记录的全部日期。触发/恢复事件中的消耗为评估当时记录,不随后续
530	 * 数据变化改写。返回进程退出码。
531	 */
532	export function cmdAlerts(opts: { ruleId: string; from?: number; to?: number }): number {
533	  let state: AlertState;
534	  let rule: AlertRule;
535	  let env: RuleEnv;
536	  try {
537	    state = loadAlertState(alertFilePath());
538	    const found = state.rules.find((r) => r.id === opts.ruleId);
539	    if (!found) {
540	      err(`unknown rule '${opts.ruleId}'`);
541	      return 1;
542	    }
543	    rule = found;
544	    env = prepareEnv(rule);
545	  } catch (e) {
546	    if (e instanceof StoreError) {
547	      err(e.message);
548	      return 1;
549	    }
550	    throw e;
551	  }
552	
553	  let dayStarts: number[];
554	  if (opts.from !== undefined && opts.to !== undefined) {
555	    dayStarts = [];
556	    for (let d = opts.from; d < opts.to; d += DAY_SECONDS) dayStarts.push(d);
557	  } else {
558	    const dates = [
559	      ...new Set(state.alerts.filter((a) => a.ruleId === rule.id).map((a) => a.date)),
560	    ].sort();
561	    dayStarts = dates.map((d) => parseIso8601(`${d}T00:00:00Z`) as number);
562	  }
563	
564	  console.log(
565	    `rule: ${rule.id}  ${targetLabel(rule)}  threshold=${formatKwh(rule.thresholdMilli)} kWh`,
566	  );
567	  if (dayStarts.length === 0) {
568	    console.log(`  no alerts recorded for rule '${rule.id}'`);
569	    return 0;
570	  }
571	
572	  const threshold = rule.thresholdMilli;
573	  for (const dayStart of dayStarts) {
574	    const date = formatIsoUtc(dayStart).slice(0, 10);
575	    const stats = computeRuleDay(rule, env, dayStart);
576	    if (stats.unknown > 0 || stats.anomaly > 0) {
577	      console.log(`  ${date}  ${undecidableReason(stats)}`);
578	    } else {
579	      const verdict = stats.consumption > threshold ? 'EXCEEDED' : 'NORMAL';
580	      console.log(
581	        `  ${date}  consumption=${formatKwh(stats.consumption)} kWh ` +
582	          `(${verdict}, threshold=${formatKwh(rule.thresholdMilli)} kWh)`,
583	      );
584	    }
585	    const alerts = state.alerts
586	      .filter((a) => a.ruleId === rule.id && a.date === date)
587	      .sort((a, b) => a.events[0].seq - b.events[0].seq);
588	    if (alerts.length === 0) {
589	      console.log('    no alerts');
590	      continue;
591	    }
592	    for (const a of alerts) {
593	      console.log(
594	        `    alert ${a.id}  status=${a.status.toUpperCase()}  ` +
595	          `ack=${a.acknowledged ? 'ACKNOWLEDGED' : 'UNACKNOWLEDGED'}`,
596	      );
597	      const events = a.events
598	        .map((e) => {
599	          const consumption =
600	            e.consumptionMilli !== undefined
601	              ? ` (consumption=${formatKwh(BigInt(e.consumptionMilli))} kWh)`
602	              : '';
603	          return `#${e.seq} ${e.type}${consumption}`;
604	        })
605	        .join(', ');
606	      console.log(`      events: ${events}`);
607	    }
608	  }
609	  return 0;
610	}
