612	/**
613	 * 按标识确认告警。已恢复告警也可确认;重复确认成功且不重复记事;
614	 * 确认不改变超限或恢复状态。返回进程退出码。
615	 */
616	export function cmdAck(alertId: string): number {
617	  const statePath = alertFilePath();
618	  let state: AlertState;
619	  try {
620	    state = loadAlertState(statePath);
621	  } catch (e) {
622	    if (e instanceof StoreError) {
623	      err(e.message);
624	      return 1;
625	    }
626	    throw e;
627	  }
628	  const alert = state.alerts.find((a) => a.id === alertId);
629	  if (!alert) {
630	    err(`unknown alert '${alertId}'`);
631	    return 1;
632	  }
633	  if (alert.acknowledged) {
634	    console.log(`alert ${alert.id} already acknowledged; unchanged`);
635	    return 0;
636	  }
637	  alert.acknowledged = true;
638	  alert.events.push({ seq: state.nextEventSeq++, type: 'acknowledged' });
639	  try {
640	    saveAlertState(statePath, state);
641	  } catch (e) {
642	    if (e instanceof StoreError) {
643	      err(e.message);
644	      return 1;
645	    }
646	    throw e;
647	  }
648	  const rule = state.rules.find((r) => r.id === alert.ruleId);
649	  const target = rule ? ` ${targetLabel(rule)}` : '';
650	  console.log(
651	    `alert ${alert.id} acknowledged (rule=${alert.ruleId}${target} date=${alert.date} status=${alert.status})`,
652	  );
653	  return 0;
654	}
