1	// group 子命令:分组成员版本配置、成员历史查询与分组能耗日报。
2	//
3	// - 分组以首次配置建立,标识非空唯一(去首尾空白、区分大小写);每次配置指定
4	//   生效时刻(含)与一整套已有设备,从该时刻起生效直到下一版本接替;允许乱序
5	//   补录历史版本。成员不能为空,同设备重复列出只算一次,成员顺序不影响等价性,
6	//   设备可属于多个分组。同组同一实际生效时刻、同成员集合重试成功且不新增,
7	//   异成员集合报冲突。
8	// - 配置整次成功或不提交:未知设备、冲突、损坏或不可读存储及写入失败都明确
9	//   报错并保留操作前状态。配置不改读数、规则和告警,导入也不改配置。
10	// - 日报按当地自然日切分(起点含、终点不含,首尾只统计重叠部分;默认 UTC,
11	//   可用 --tz 指定 IANA 时区,时区只决定分日),按当时生效成员计算,不把
12	//   最新成员套用到历史;首个版本生效前记为未知。各设备使用完整已存时序,
13	//   区间两端读数即使在查询范围外也参与;成员切换不需要恰好有读数,首条
14	//   读数之前、末条之后及孤立读数时段为未知,不外推。
15	// - 每个时段只有全部生效成员均处于非下降读数区间时才是有效覆盖,并计入成员
16	//   消耗之和;任一成员下降则为异常覆盖,否则任一成员未知则为未知覆盖。异常与
17	//   未知时段不计任何成员消耗,不以缺失设备为零补齐。覆盖秒数按分组实际时间
18	//   计算,不累加成员秒数。各设备片段仍以原读数区间起点累计比例向下取整,
19	//   两端累计量之差为消耗;日界线、查询边界与成员切换均不重置分摊起点,
20	//   拆开查询相加结果一致。全程 BigInt 精确计算,kWh 固定三位小数。
21	// - 日报与历史只读;读取读数时拒绝同设备同一实际时刻的多条存储记录。
22	
23	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
24	import { dirname } from 'node:path';
25	import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
26	import { formatIsoUtc } from './time.ts';
27	import { localDays, loadTimezone } from './tz.ts';
28	import { formatKwh } from './value.ts';
29	
30	export interface GroupVersion {
31	  /** 生效时刻(含),epoch 秒。 */
32	  at: number;
33	  /** 成员设备标识,已去重并按字典序排序(规范形,成员顺序不影响等价性)。 */
34	  members: string[];
35	}
36	
37	export interface Group {
38	  /** 分组标识(非空、唯一,已去首尾空白,区分大小写)。 */
39	  id: string;
40	  /** 成员版本,按生效时刻升序。 */
41	  versions: GroupVersion[];
42	}
43	
44	function err(message: string): void {
45	  console.error(`meterwatch: ${message}`);
46	}
47	
48	/** 读取分组存储;文件不存在返回空数组,存在但无法读取或内容损坏抛出 StoreError。 */
49	export function loadGroups(path: string): Group[] {
50	  let text: string;
51	  try {
52	    text = readFileSync(path, 'utf8');
53	  } catch (e) {
54	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return [];
55	    throw new StoreError(`cannot read storage file ${path}: ${(e as Error).message}`);
56	  }
57	  let data: unknown;
58	  try {
59	    data = JSON.parse(text);
60	  } catch {
61	    throw new StoreError(`storage file ${path} is corrupted (invalid JSON)`);
62	  }
63	  const bad = (what: string): StoreError =>
64	    new StoreError(`storage file ${path} is corrupted (${what})`);
65	  const o = data as Record<string, unknown>;
66	  if (o === null || typeof o !== 'object') throw bad('not an object');
67	  if (!Array.isArray(o.groups)) throw bad('missing groups array');
68	
69	  const ids = new Set<string>();
70	  const groups: Group[] = [];
71	  for (const g of o.groups as Array<Record<string, unknown>>) {
72	    const ok =
73	      g !== null &&
74	      typeof g === 'object' &&
75	      typeof g.id === 'string' &&
76	      g.id.length > 0 &&
77	      Array.isArray(g.versions) &&
78	      g.versions.length > 0;
79	    if (!ok) throw bad('invalid group entry');
80	    if (ids.has(g.id as string)) throw bad(`duplicate group id '${g.id}'`);
81	    ids.add(g.id as string);
82	
83	    const versions: GroupVersion[] = [];
84	    const seenAts = new Set<number>();
85	    for (const v of g.versions as Array<Record<string, unknown>>) {
86	      const vok =
87	        v !== null &&
88	        typeof v === 'object' &&
89	        Number.isSafeInteger(v.at) &&
90	        Array.isArray(v.members) &&
91	        v.members.length > 0 &&
92	        (v.members as unknown[]).every((m) => typeof m === 'string' && (m as string).length > 0);
93	      if (!vok) throw bad(`invalid version entry in group '${g.id}'`);
94	      const at = v.at as number;
95	      if (seenAts.has(at)) throw bad(`duplicate version time in group '${g.id}'`);
96	      seenAts.add(at);
97	      const members = [...(v.members as string[])].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
98	      for (let i = 1; i < members.length; i++) {
99	        if (members[i] === members[i - 1]) {
100	          throw bad(`duplicate member '${members[i]}' in group '${g.id}'`);
101	        }
102	      }
103	      versions.push({ at, members });
104	    }
105	    versions.sort((a, b) => a.at - b.at);
106	    groups.push({ id: g.id as string, versions });
107	  }
108	  return groups;
109	}
110	
111	/** 原子写入分组存储;失败抛错,原有数据保持不变。 */
112	function saveGroups(path: string, groups: Group[]): void {
113	  mkdirSync(dirname(path), { recursive: true });
114	  const tmp = `${path}.tmp-${process.pid}`;
115	  const body = JSON.stringify({ version: 1, groups }, null, 2) + '\n';
116	  try {
117	    writeFileSync(tmp, body, 'utf8');
118	    renameSync(tmp, path);
119	  } catch (e) {
120	    throw new StoreError(`cannot write storage file ${path}: ${(e as Error).message}`);
121	  }
122	}
123	
124	/**
125	 * 载入读数并按设备分组,各组时序按时刻排序。
126	 * 任一设备(包括未被任何分组引用的设备)同一实际时刻存在多条存储记录时
127	 * 抛 StoreError:新功能拒绝全库重复身份,而不只是成员设备。
128	 */
129	export function loadCheckedSeriesByDevice(all: Reading[]): Map<string, Reading[]> {
130	  const byDevice = new Map<string, Reading[]>();
131	  for (const r of all) {
132	    const list = byDevice.get(r.device);
133	    if (list) list.push(r);
134	    else byDevice.set(r.device, [r]);
135	  }
136	  for (const [device, list] of byDevice) {
137	    list.sort((a, b) => a.ts - b.ts);
138	    for (let i = 1; i < list.length; i++) {
139	      if (list[i].ts === list[i - 1].ts) {
140	        throw new StoreError(
141	          `storage error: multiple stored readings for device '${device}' at ${formatIsoUtc(list[i].ts)}`,
142	        );
143	      }
144	    }
145	  }
146	  return byDevice;
147	}
148	
149	/** 在按时刻升序的时序中找最后一条 ts <= s 的下标,无则 -1。 */
150	function floorIndex(series: Reading[], s: number): number {
151	  let lo = 0;
152	  let hi = series.length - 1;
153	  let ans = -1;
154	  while (lo <= hi) {
155	    const mid = (lo + hi) >> 1;
156	    if (series[mid].ts <= s) {
157	      ans = mid;
158	      lo = mid + 1;
159	    } else {
160	      hi = mid - 1;
161	    }
162	  }
163	  return ans;
164	}
165	
166	type SliceKind = 'valid' | 'anomaly' | 'unknown';
167	
168	/**
169	 * 单设备在片段 [s, e) 上的状态与消耗。片段完全落在同一读数区间内
170	 * (调用方保证切点包含区间内全部读数时刻)。非下降区间以区间起点累计
171	 * 比例向下取整,消耗为两端累计量之差;下降区间为异常;首条读数之前、
172	 * 末条之后及孤立读数时段为未知,不外推。
173	 */
174	function deviceSlice(
175	  series: Reading[],
176	  s: number,
177	  e: number,
178	): { kind: SliceKind; consumption: bigint } {
179	  const i = floorIndex(series, s);
180	  if (i < 0 || i + 1 >= series.length) return { kind: 'unknown', consumption: 0n };
181	  const a = series[i];
182	  const b = series[i + 1];
183	  const diff = b.milli - a.milli;
184	  if (diff < 0n) return { kind: 'anomaly', consumption: 0n };
185	  const duration = BigInt(b.ts - a.ts);
186	  const cumulative = (t: number): bigint => (diff * BigInt(t - a.ts)) / duration;
187	  return { kind: 'valid', consumption: cumulative(e) - cumulative(s) };
188	}
189	
190	export interface GroupPeriod {
191	  /** 时段起点(含),epoch 秒。 */
192	  start: number;
193	  /** 时段终点(不含),epoch 秒。 */
194	  end: number;
195	  /** 该时段生效成员;null 表示首个版本生效前(未知)。 */
196	  members: string[] | null;
197	}
198	
199	export interface GroupSegmentStats {
200	  /** 有效(全部成员非下降)覆盖秒数,按分组实际时间计。 */
201	  valid: number;
202	  /** 异常(任一成员下降)覆盖秒数。 */
203	  anomaly: number;
204	  /** 未知(无生效版本或任一成员未知)覆盖秒数。 */
205	  unknown: number;
206	  /** 有效时段内全部生效成员的分摊消耗之和,毫千瓦时 BigInt。 */
207	  consumption: bigint;
208	  /** 段内按生效时刻切分的成员时段。 */
209	  periods: GroupPeriod[];
210	}
211	
212	/**
213	 * 计算分组在 [segStart, segEnd) 上的覆盖与消耗。
214	 * versions 按生效时刻升序;seriesByDevice 含全部版本成员的完整时序。
215	 */
216	export function computeGroupSegment(
217	  versions: GroupVersion[],
218	  seriesByDevice: Map<string, Reading[]>,
219	  segStart: number,
220	  segEnd: number,
221	): GroupSegmentStats {
222	  // 按版本生效时刻把段切成成员恒定的时段;首个版本生效前 members 为 null。
223	  const periods: GroupPeriod[] = [];
224	  let idx = -1;
225	  for (let i = 0; i < versions.length; i++) {
226	    if (versions[i].at <= segStart) idx = i;
227	    else break;
228	  }
229	  let cursor = segStart;
230	  while (cursor < segEnd) {
231	    const nextAt = idx + 1 < versions.length ? versions[idx + 1].at : Number.POSITIVE_INFINITY;
232	    const pEnd = Math.min(segEnd, nextAt);
233	    periods.push({ start: cursor, end: pEnd, members: idx >= 0 ? versions[idx].members : null });
234	    cursor = pEnd;
235	    idx++;
236	  }
237	
238	  let valid = 0;
239	  let anomaly = 0;
240	  let unknown = 0;
241	  let consumption = 0n;
242	  for (const p of periods) {
243	    if (p.members === null) {
244	      unknown += p.end - p.start;
245	      continue;
246	    }
247	    // 切点:时段边界与全部成员的读数时刻;相邻切点间每个成员的状态恒定。
248	    const bounds = new Set<number>([p.start, p.end]);
249	    for (const m of p.members) {
250	      for (const r of seriesByDevice.get(m) ?? []) {
251	        if (r.ts > p.start && r.ts < p.end) bounds.add(r.ts);
252	      }
253	    }
254	    const sorted = [...bounds].sort((a, b) => a - b);
255	    for (let k = 0; k + 1 < sorted.length; k++) {
256	      const s = sorted[k];
257	      const e = sorted[k + 1];
258	      let anyAnomaly = false;
259	      let anyUnknown = false;
260	      let slice = 0n;
261	      for (const m of p.members) {
262	        const res = deviceSlice(seriesByDevice.get(m) ?? [], s, e);
263	        if (res.kind === 'anomaly') anyAnomaly = true;
264	        else if (res.kind === 'unknown') anyUnknown = true;
265	        else slice += res.consumption;
266	      }
267	      if (anyAnomaly) {
268	        anomaly += e - s;
269	      } else if (anyUnknown) {
270	        unknown += e - s;
271	      } else {
272	        valid += e - s;
273	        consumption += slice;
274	      }
275	    }
276	  }
277	  return { valid, anomaly, unknown, consumption, periods };
278	}
279	
280	/**
281	 * 配置分组成员版本。首次配置即建立分组;同组同一实际生效时刻、同成员集合
282	 * 重试成功且不新增,异成员集合报冲突。整次成功或不提交。返回进程退出码。
283	 */
284	export function cmdGroupConfigure(opts: { id: string; at: number; members: string[] }): number {
285	  const path = groupFilePath();
286	  let groups: Group[];
287	  try {
288	    groups = loadGroups(path);
289	  } catch (e) {
290	    if (e instanceof StoreError) {
291	      err(e.message);
292	      return 1;
293	    }
294	    throw e;
295	  }
296	
297	  // 规范形:同设备重复列出只算一次,成员顺序不影响等价性。
298	  const members = [...new Set(opts.members)].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
299	
300	  let known: Set<string>;
301	  try {
302	    known = new Set(loadStore(dataFilePath()).map((r) => r.device));
303	  } catch (e) {
304	    if (e instanceof StoreError) {
305	      err(e.message);
306	      return 1;
307	    }
308	    throw e;
309	  }
310	  for (const m of members) {
311	    if (!known.has(m)) {
312	      err(`unknown device '${m}': no stored readings; import readings before configuring a group`);
313	      return 1;
314	    }
315	  }
316	
317	  const existing = groups.find((g) => g.id === opts.id);
318	  if (existing) {
319	    const v = existing.versions.find((ver) => ver.at === opts.at);
320	    if (v) {
321	      const same =
322	        v.members.length === members.length && v.members.every((m, i) => m === members[i]);
323	      if (same) {
324	        console.log(
325	          `group '${opts.id}' already has an identical member version at ${formatIsoUtc(opts.at)}; unchanged`,
326	        );
327	        return 0;
328	      }
329	      err(
330	        `group '${opts.id}' already has a different member version at ${formatIsoUtc(opts.at)} ` +
331	          `(stored members=${v.members.join(',')}, got members=${members.join(',')}); conflict`,
332	      );
333	      return 1;
334	    }
335	    existing.versions.push({ at: opts.at, members });
336	    existing.versions.sort((a, b) => a.at - b.at);
337	  } else {
338	    groups.push({ id: opts.id, versions: [{ at: opts.at, members }] });
339	  }
340	
341	  try {
342	    saveGroups(path, groups);
343	  } catch (e) {
344	    if (e instanceof StoreError) {
345	      err(e.message);
346	      return 1;
347	    }
348	    throw e;
349	  }
350	  console.log(
351	    `group '${opts.id}' configured: members=${members.join(',')} effective ${formatIsoUtc(opts.at)}`,
352	  );
353	  return 0;
354	}
355	
356	/** 查看分组成员版本历史,按生效时刻排序。只读。返回进程退出码。 */
357	export function cmdGroupHistory(opts: { id: string }): number {
358	  let groups: Group[];
359	  try {
360	    groups = loadGroups(groupFilePath());
361	  } catch (e) {
362	    if (e instanceof StoreError) {
363	      err(e.message);
364	      return 1;
365	    }
366	    throw e;
367	  }
368	  const group = groups.find((g) => g.id === opts.id);
369	  if (!group) {
370	    err(`unknown group '${opts.id}'`);
371	    return 1;
372	  }
373	  console.log(`group: ${group.id}`);
374	  for (const v of group.versions) {
375	    console.log(`  ${formatIsoUtc(v.at)}  members=${v.members.join(',')}`);
376	  }
377	  return 0;
378	}
379	
380	/**
381	 * 分组能耗日报:按当地自然日切分(默认 UTC,--tz 指定 IANA 时区),按当时
382	 * 生效成员计算。只读,不写入数据。返回进程退出码。
383	 */
384	export function cmdGroupDaily(opts: { id: string; from: number; to: number; tz?: string }): number {
385	  const tzName = opts.tz ?? 'UTC';
386	  const tz = loadTimezone(tzName);
387	  if (!tz) {
388	    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
389	    return 2;
390	  }
391	
392	  let groups: Group[];
393	  try {
394	    groups = loadGroups(groupFilePath());
395	  } catch (e) {
396	    if (e instanceof StoreError) {
397	      err(e.message);
398	      return 1;
399	    }
400	    throw e;
401	  }
402	  const group = groups.find((g) => g.id === opts.id);
403	  if (!group) {
404	    err(`unknown group '${opts.id}'`);
405	    return 1;
406	  }
407	
408	  let seriesByDevice: Map<string, Reading[]>;
409	  try {
410	    seriesByDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
411	  } catch (e) {
412	    if (e instanceof StoreError) {
413	      err(e.message);
414	      return 1;
415	    }
416	    throw e;
417	  }
418	
419	  const days = localDays(tz, opts.from, opts.to);
420	
421	  console.log(`group: ${group.id}`);
422	  console.log(`timezone: ${tzName}`);
423	  let total = 0n;
424	  let computedDays = 0;
425	  let incomplete = false;
426	  for (const day of days) {
427	    let valid = 0;
428	    let anomaly = 0;
429	    let unknown = 0;
430	    let consumption = 0n;
431	    const periods: GroupPeriod[] = [];
432	    for (const p of day.periods) {
433	      const stats = computeGroupSegment(group.versions, seriesByDevice, p.start, p.end);
434	      valid += stats.valid;
435	      anomaly += stats.anomaly;
436	      unknown += stats.unknown;
437	      consumption += stats.consumption;
438	      periods.push(...stats.periods);
439	    }
440	    const dayIncomplete = anomaly > 0 || unknown > 0;
441	    if (dayIncomplete) incomplete = true;
442	
443	    let consumptionText: string;
444	    if (valid > 0) {
445	      consumptionText = `consumption=${formatKwh(consumption)} kWh (estimate)`;
446	      total += consumption;
447	      computedDays++;
448	    } else {
449	      consumptionText = 'consumption=n/a (no valid coverage)';
450	    }
451	    let line =
452	      `  ${day.label}  ${consumptionText}` +
453	      `  valid=${valid}s  anomaly=${anomaly}s  unknown=${unknown}s`;
454	    if (dayIncomplete) line += '  INCOMPLETE';
455	    console.log(line);
456	    for (const p of day.periods) {
457	      console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
458	    }
459	    for (const p of periods) {
460	      const members = p.members === null ? '(no version in effect)' : p.members.join(',');
461	      console.log(
462	        `    members=${members}  period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`,
463	      );
464	    }
465	  }
466	
467	  const totalText =
468	    computedDays > 0
469	      ? `total consumption=${formatKwh(total)} kWh (estimate)`
470	      : 'total consumption=n/a (no valid coverage)';
471	  const status = incomplete
472	    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
473	    : 'status=complete';
474	  console.log(
475	    `  summary: group=${group.id}  computed=${computedDays}/${days.length} day(s)  ${totalText}  ${status}`,
476	  );
477	  return 0;
478	}
