1	// 本地持久化:JSON 文件,默认位于 ~/.meterwatch/readings.json,
2	// 可用环境变量 METERWATCH_DATA_DIR 指定其他目录。
3	// 写入采用临时文件 + rename 的原子方式;读取失败或内容损坏一律报错,绝不当作空库。
4	//
5	// 毫千瓦时数值在文件中以十进制字符串保存,可表示任意大的精确值;
6	// 同时兼容旧版以 JSON 数值保存的安全整数读数。数值型毫千瓦时若超出
7	// Number 安全整数范围,JSON 解析时已丢失精度,按损坏数据拒绝,不猜测原值。
8	
9	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
10	import { homedir } from 'node:os';
11	import { dirname, join } from 'node:path';
12	
13	export interface Reading {
14	  /** 设备标识(已去除首尾空白,区分大小写)。 */
15	  device: string;
16	  /** 实际时刻,epoch 秒。 */
17	  ts: number;
18	  /** 累计读数,毫千瓦时(千分之一 kWh)BigInt,非负。 */
19	  milli: bigint;
20	}
21	
22	export interface CorrectionItem {
23	  /** 设备标识(已去除首尾空白,区分大小写)。 */
24	  device: string;
25	  /** 实际时刻,epoch 秒。 */
26	  ts: number;
27	  /** 提交时核验的预期原值,毫千瓦时 BigInt。 */
28	  expectedMilli: bigint;
29	  /** 替换值,毫千瓦时 BigInt。 */
30	  replacementMilli: bigint;
31	}
32	
33	export interface Correction {
34	  /** 请求标识(已去除首尾空白,区分大小写),在数据目录内唯一。 */
35	  requestId: string;
36	  /** 本次提交的修正项,按提交顺序保存。 */
37	  items: CorrectionItem[];
38	}
39	
40	export interface UndoRecord {
41	  /** 撤销请求标识(已去除首尾空白,区分大小写),与修正请求共用唯一标识空间。 */
42	  requestId: string;
43	  /** 目标修正请求标识;只能是成功修正,不能是撤销请求。 */
44	  targetId: string;
45	  /** 首次撤销时实际恢复的读数条数(目标中实际改变过的项)。 */
46	  restored: number;
47	}
48	
49	export interface StoreData {
50	  readings: Reading[];
51	  /** 已成功提交的修正历史,按提交顺序;与读数同文件原子持久化。 */
52	  corrections: Correction[];
53	  /** 已成功提交的撤销记录,按成功发生顺序;与读数、修正历史同文件原子持久化。 */
54	  undos: UndoRecord[];
55	}
56	
57	export class StoreError extends Error {}
58	
59	export function dataFilePath(): string {
60	  const dir = process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
61	  return join(dir, 'readings.json');
62	}
63	
64	/** 告警规则与历史的存储文件,与读数文件同目录、相互独立。 */
65	export function alertFilePath(): string {
66	  const dir = process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
67	  return join(dir, 'alerts.json');
68	}
69	
70	/** 分组配置的存储文件,与读数、告警文件同目录、相互独立。 */
71	export function groupFilePath(): string {
72	  const dir = process.env.METERWATCH_DATA_DIR ?? join(homedir(), '.meterwatch');
73	  return join(dir, 'groups.json');
74	}
75	
76	/**
77	 * 解析存储中的毫千瓦时字段:十进制数字字符串,或旧格式的安全整数数值。
78	 * 其他形式(含超出安全整数范围的数值,精度已丢失)返回 null,由调用方按损坏处理。
79	 */
80	export function parseStoredMilli(value: unknown): bigint | null {
81	  if (typeof value === 'string' && /^\d+$/.test(value)) return BigInt(value);
82	  if (typeof value === 'number' && Number.isSafeInteger(value) && value >= 0) {
83	    return BigInt(value);
84	  }
85	  return null;
86	}
87	
88	/**
89	 * 解析存储中的修正历史;字段缺失按空历史(旧版文件),存在但结构非法返回 null。
90	 */
91	function parseStoredCorrections(value: unknown): Correction[] | null {
92	  if (value === undefined) return [];
93	  if (!Array.isArray(value)) return null;
94	  const out: Correction[] = [];
95	  const ids = new Set<string>();
96	  for (const c of value as Array<Record<string, unknown>>) {
97	    if (
98	      c === null ||
99	      typeof c !== 'object' ||
100	      typeof c.requestId !== 'string' ||
101	      c.requestId.length === 0 ||
102	      !Array.isArray(c.items) ||
103	      c.items.length === 0 ||
104	      ids.has(c.requestId)
105	    ) {
106	      return null;
107	    }
108	    const items: CorrectionItem[] = [];
109	    for (const it of c.items as Array<Record<string, unknown>>) {
110	      const expectedMilli = it !== null && typeof it === 'object' ? parseStoredMilli(it.expectedMilli) : null;
111	      const replacementMilli = it !== null && typeof it === 'object' ? parseStoredMilli(it.replacementMilli) : null;
112	      const ok =
113	        it !== null &&
114	        typeof it === 'object' &&
115	        typeof it.device === 'string' &&
116	        it.device.length > 0 &&
117	        Number.isSafeInteger(it.ts) &&
118	        expectedMilli !== null &&
119	        replacementMilli !== null;
120	      if (!ok) return null;
121	      items.push({
122	        device: it.device as string,
123	        ts: it.ts as number,
124	        expectedMilli: expectedMilli as bigint,
125	        replacementMilli: replacementMilli as bigint,
126	      });
127	    }
128	    ids.add(c.requestId);
129	    out.push({ requestId: c.requestId, items });
130	  }
131	  return out;
132	}
133	
134	/**
135	 * 解析存储中的撤销历史;字段缺失按空历史(旧版文件,原修正视为未撤销),
136	 * 存在但结构非法或与修正历史不一致返回 null。
137	 */
138	function parseStoredUndos(value: unknown, corrections: Correction[]): UndoRecord[] | null {
139	  if (value === undefined) return [];
140	  if (!Array.isArray(value)) return null;
141	  const correctionIds = new Set(corrections.map((c) => c.requestId));
142	  const ids = new Set<string>();
143	  const targets = new Set<string>();
144	  const out: UndoRecord[] = [];
145	  for (const u of value as Array<Record<string, unknown>>) {
146	    const ok =
147	      u !== null &&
148	      typeof u === 'object' &&
149	      typeof u.requestId === 'string' &&
150	      u.requestId.length > 0 &&
151	      typeof u.targetId === 'string' &&
152	      u.targetId.length > 0 &&
153	      Number.isSafeInteger(u.restored) &&
154	      (u.restored as number) >= 0;
155	    if (!ok) return null;
156	    // 撤销与修正共用唯一标识空间;目标必须是已存修正且每个目标最多被撤销一次。
157	    if (ids.has(u.requestId as string) || correctionIds.has(u.requestId as string)) return null;
158	    if (!correctionIds.has(u.targetId as string) || targets.has(u.targetId as string)) return null;
159	    ids.add(u.requestId as string);
160	    targets.add(u.targetId as string);
161	    out.push({
162	      requestId: u.requestId as string,
163	      targetId: u.targetId as string,
164	      restored: u.restored as number,
165	    });
166	  }
167	  return out;
168	}
169	
170	/** 读取存储(读数与修正历史);文件不存在返回空数据,存在但无法读取或内容损坏抛出 StoreError。 */
171	export function loadData(path: string): StoreData {
