/** 解析 YYYY-MM-DD 日期选项为当地日期标签;无效时返回错误消息字符串。 */
function dateFlag(value: string, label: string): { date: string } | string {
  const v = value.trim();
  if (parseUtcDate(v) === null) {
    return `${label}无效: '${v}'(需 YYYY-MM-DD 的真实日期)`;
  }
  return { date: v };
}

